      { name:"Render", parent:"Render Services Inc.", hq:"San Francisco, CA", jurisdiction:"United States", cloudAct:true, dataResidency:"US/EU", note:"US-incorporated cloud hosting. Popular with startups for deploying web apps. No Canadian region available. Application data and environment secrets under US jurisdiction.", risk:"exposed", category:"cloud_infrastructure", industries:["technology"] },
      { name:"Vultr", parent:"The Constant Company LLC", hq:"Matawan, NJ", jurisdiction:"United States", cloudAct:true, dataResidency:"Global (32 locations)", note:"US-incorporated cloud hosting with Toronto data centre. Canadian data residency available for compute/storage. However, US-parent means CLOUD Act compelled disclosure applies even to Toronto-hosted data.", risk:"review", category:"cloud_infrastructure", industries:["technology"] },
      { name:"Hetzner", parent:"Hetzner Online GmbH", hq:"Gunzenhausen, Germany", jurisdiction:"Germany / EU", cloudAct:false, dataResidency:"EU", note:"German-incorporated cloud hosting and dedicated servers. No Canadian data centre but strong EU data protection. Cost-effective alternative to US cloud providers. Not subject to US CLOUD Act. GDPR-compliant.", risk:"non_exposed", category:"cloud_infrastructure", industries:["technology"] },
      { name:"OVHcloud", parent:"OVH Groupe S.A.", hq:"Roubaix, France", jurisdiction:"France / EU", cloudAct:false, dataResidency:"EU/Canada", note:"French-incorporated (Euronext-listed) cloud provider. Canadian data centre in Beauharnois, QC. Not subject to US CLOUD Act. Investing in Canadian sovereign cloud infrastructure.", risk:"non_exposed", category:"cloud_infrastructure", industries:["technology","government"] },
      { name:"Linode", parent:"Akamai Technologies Inc.", hq:"Philadelphia, PA", jurisdiction:"United States", cloudAct:true, dataResidency:"US/Toronto available", note:"US-incorporated (acquired by Akamai 2022) cloud computing platform. Toronto data centre available. IaaS — customer controls data but platform under US jurisdiction.", risk:"review", category:"cloud_infrastructure", industries:["technology"] },
      { name:"Civo", parent:"Civo Ltd.", hq:"Stevenage, United Kingdom", jurisdiction:"United Kingdom", cloudAct:false, dataResidency:"UK/EU/US", note:"UK-incorporated cloud-native Kubernetes hosting. Not subject to US CLOUD Act. Developer-focused alternative to major US cloud providers.", risk:"non_exposed", category:"cloud_infrastructure", industries:["technology"] },
      { name:"Scaleway", parent:"Iliad SA", hq:"Paris, France", jurisdiction:"France", cloudAct:false, dataResidency:"EU", note:"French-incorporated (Iliad subsidiary) European cloud provider. All data centres in EU. Strong data sovereignty positioning. Not subject to CLOUD Act.", risk:"non_exposed", category:"cloud_infrastructure", industries:["technology","government"] },
      { name:"ThinkOn", parent:"Think On Inc.", hq:"Etobicoke, ON", jurisdiction:"Canada", cloudAct:false, dataResidency:"Canada", note:"100% Canadian-owned and operated cloud service provider. First Canadian VMware Sovereign Cloud partner. Only Canadian CSP authorized for Protected-B government workloads under GC Cloud Framework Agreement. Part of consortium (with Hypertec, Aptum, eStruxture) building Canada's first end-to-end sovereign government cloud. Channel-only model. Not subject to any foreign data access laws.", risk:"canadian", category:"cloud_infrastructure", industries:["technology","government","healthcare","finance","education"] },
      { name:"Micrologic", parent:"Micrologic Inc.", hq:"Quebec City, QC", jurisdiction:"Canada", cloudAct:false, dataResidency:"Canada", note:"100% Canadian-owned sovereign cloud provider. Founded 1983 in Quebec City. Only Canadian sovereign cloud recognized by Gartner in the Operational Sovereignty category. Cirrus cloud platform powered by VMware. $150M pan-Canadian expansion underway. ISO 27001, ISO 27017, ISO 27018 certified. Qualified for PSPC SaaS catalogue. Not subject to any foreign jurisdiction.", risk:"canadian", category:"cloud_infrastructure", industries:["technology","government","healthcare","finance"] },
      { name:"eStruxture", parent:"eStruxture Data Centers Inc.", hq:"Montreal, QC", jurisdiction:"Canada", cloudAct:false, dataResidency:"Canada", note:"Largest Canadian-owned data centre provider. 16 facilities across Montreal, Toronto, Vancouver, Calgary. 760,000+ sq ft of data centre space. Founded 2017. Majority-owned by Fengate Asset Management (Canadian). Provides colocation, cloud connectivity, and managed services. Part of sovereign government cloud consortium with ThinkOn, Hypertec, and Aptum.", risk:"canadian", category:"cloud_infrastructure", industries:["technology","finance","government","healthcare"] },
      { name:"Hypertec Cloud", parent:"Hypertec Group", hq:"Montreal, QC (Saint-Laurent)", jurisdiction:"Canada", cloudAct:false, dataResidency:"Canada", note:"100% Canadian-owned. Founded 1984. Cloud infrastructure division formed via acquisition of cloud.ca in 2021. NVIDIA Canadian Partner of the Year 2025. Only Canadian-headquartered OEM for NVIDIA. Capacity for 100,000 GPUs. Hardware designed and assembled in Montreal. Part of sovereign government cloud consortium. Sovereign AI Research Hub with Mila. Partnership with Bell for sovereign AI infrastructure.", risk:"canadian", category:"cloud_infrastructure", industries:["technology","government","healthcare","finance"] },
      { name:"Aptum", parent:"Aptum Technologies Inc.", hq:"Toronto, ON", jurisdiction:"Canada", cloudAct:false, dataResidency:"Canada/US/UK", note:"Canadian-headquartered (Toronto) multi-cloud managed service provider. Formerly Cogeco Peer 1. Owned by DigitalBridge (US PE firm) — ownership structure introduces potential foreign influence though company operates under Canadian jurisdiction. Acquired CloudOps (Montreal) in 2023. Part of sovereign government cloud consortium providing orchestration and governance platform.", risk:"review", category:"cloud_infrastructure", industries:["technology","government","finance"] },
      { name:"Bell Cloud / AI Fabric", parent:"BCE Inc.", hq:"Montreal, QC", jurisdiction:"Canada", cloudAct:false, dataResidency:"Canada", note:"Bell Canada's sovereign cloud and AI infrastructure platform. $500M investment in hydro-powered AI data centres in British Columbia. Partnered with SAP Canada for sovereign cloud (Feb 2026) and Hypertec for sovereign AI compute. Canadian-owned (BCE Inc., TSX/NYSE listed). Canadian-incorporated, subject to Canadian law.", risk:"canadian", category:"cloud_infrastructure", industries:["technology","government","healthcare","finance"] },
      { name:"TELUS Cloud", parent:"TELUS Corporation", hq:"Vancouver, BC", jurisdiction:"Canada", cloudAct:false, dataResidency:"Canada", note:"TELUS sovereign cloud infrastructure. Data centres in Rimouski, QC and Kamloops, BC. Partnered with OpenText to launch Canadian Sovereign Cloud (July 2025) — enterprise-grade cloud and AI operating entirely within Canadian borders. Canadian-owned (TELUS Corp., TSX/NYSE listed). Not subject to foreign data access laws.", risk:"canadian", category:"cloud_infrastructure", industries:["technology","government","healthcare","finance"] },
      { name:"OpenText Sovereign Cloud", parent:"Open Text Corporation", hq:"Waterloo, ON", jurisdiction:"Canada", cloudAct:false, dataResidency:"Canada", note:"Canadian-incorporated (NASDAQ/TSX listed). Partnered with TELUS to launch Canadian Sovereign Cloud (Sept 2025). Serves 1,600 Canadian institutions. Private cloud solutions available through PSPC procurement. AI capabilities via Aviator platform hosted entirely in Canada. Early signatory of Government of Canada voluntary AI code of conduct.", risk:"canadian", category:"cloud_infrastructure", industries:["technology","government","healthcare","finance"] },
      { name:"Vertafore", parent:"Roper Technologies Inc. (NYSE: ROP)", hq:"Denver, CO", jurisdiction:"United States", cloudAct:true, dataResidency:"US", note:"US-incorporated insurance technology company. Parent Roper Technologies (NYSE: ROP, Sarasota FL) acquired Vertafore in 2020 for $5.35B. Products include AMS360, Sircon, PL Rating. Processes policyholder PII, policy details, claims data. Keal (Canadian brand) is a Vertafore subsidiary.", risk:"exposed", category:"insurance", industries:["insurance"] },
      { name:"Keal", parent:"Roper Technologies Inc. (via Vertafore)", hq:"Montreal, QC", jurisdiction:"United States", cloudAct:true, dataResidency:"Canada/US", note:"Montreal-based insurance BMS branded as Canadian but owned by Vertafore → Roper Technologies (NYSE: ROP). Keal sigXP is widely used by Quebec brokerages. Canadian office and servers but US parent means CLOUD Act applies. Feels Canadian — it is not.", risk:"exposed", category:"insurance", industries:["insurance"] },
      { name:"Applied Epic", parent:"Applied Systems Inc.", hq:"University Park, IL", jurisdiction:"United States", cloudAct:true, dataResidency:"US/Canada", note:"US-incorporated insurance technology platform backed by consortium of US PE firms: Hellman & Friedman, CapitalG (Alphabet), JMI Equity, Stone Point Capital. Dominant BMS in North American commercial insurance. Applied Epic processes full policyholder lifecycle data. Canadian data centre available.", risk:"exposed", category:"insurance", industries:["insurance"] },
      { name:"Power Broker", parent:"Acturis Group Ltd. (via Astorg Partners)", hq:"London, UK / Luxembourg", jurisdiction:"United Kingdom", cloudAct:false, dataResidency:"UK/Canada", note:"UK-incorporated insurance BMS. Acturis Group backed by Astorg Partners (Luxembourg PE). Power Broker is the Canadian-market brand. Processes policyholder data, policy details, claims. Not CLOUD Act exposed but UK Investigatory Powers Act applies.", risk:"review", category:"insurance", industries:["insurance"] },
      { name:"Compu-Quote", parent:"Applied Systems Inc.", hq:"University Park, IL", jurisdiction:"United States", cloudAct:true, dataResidency:"US", note:"Canadian personal lines rating engine owned by Applied Systems (US PE-backed). Used by Canadian brokerages for auto/home quoting. Processes applicant personal information including driving records, property details, coverage history. CLOUD Act applies via Applied Systems.", risk:"exposed", category:"insurance", industries:["insurance"] },
      { name:"Rival Insurance Technology", parent:"Rival Insurance Technology Inc.", hq:"Toronto, ON", jurisdiction:"Canada", cloudAct:false, dataResidency:"Canada", note:"Canadian-incorporated insurance technology company. TBW Flex platform — broker management system built for Canadian market. One of the few remaining Canadian-owned BMS providers after industry consolidation to US PE. Toronto HQ.", risk:"canadian", category:"insurance", industries:["insurance"] },
      { name:"ShowingTime", parent:"Zillow Group Inc. (NASDAQ: Z/ZG)", hq:"Chicago, IL", jurisdiction:"United States", cloudAct:true, dataResidency:"US", note:"Acquired by Zillow Group for ~$500M. Showing scheduling and management for real estate. Processes showing requests with buyer/seller names, property addresses, agent details, showing times. Physical security implications — showing data reveals when homes are occupied/vacant.", risk:"exposed", category:"real_estate", industries:["real_estate"] },
      { name:"CREA WEBForms", parent:"Canadian Real Estate Association", hq:"Ottawa, ON", jurisdiction:"Canada", cloudAct:false, dataResidency:"Canada", note:"Owned and operated by CREA (Canadian Real Estate Association). Web-based forms platform for purchase agreements, listings, and real estate transaction documents. The only clean Canadian real estate transaction tool. All data under Canadian jurisdiction.", risk:"canadian", category:"real_estate", industries:["real_estate"] },
      { name:"Mindbody", parent:"Mindbody Inc. (Vista Equity Partners)", hq:"San Luis Obispo, CA", jurisdiction:"United States", cloudAct:true, dataResidency:"US", note:"Acquired by Vista Equity Partners (Austin TX) for $1.9B in Feb 2019. Dominant fitness/wellness management platform globally. Also owns ClassPass (acquired Oct 2021). Delaware court ruled the acquisition was 'corrupted' — founder colluded with Vista, $48M judgment. Processes member records, class bookings, payments, health intake forms.", risk:"exposed", category:"fitness", industries:["fitness","wellness"] },
      { name:"ClassPass", parent:"Mindbody Inc. (Vista Equity Partners)", hq:"New York, NY", jurisdiction:"United States", cloudAct:true, dataResidency:"US", note:"Acquired by Mindbody (Vista Equity Partners) in October 2021. Fitness class marketplace. Member profiles, booking history, payment data, location data all under US PE control via Mindbody/Vista.", risk:"exposed", category:"fitness", industries:["fitness","wellness"] },
      { name:"Trainerize", parent:"ABC Fitness Solutions LLC", hq:"Vancouver, BC (was)", jurisdiction:"United States", cloudAct:true, dataResidency:"US", note:"Founded in Vancouver BC. Acquired by ABC Fitness Solutions (Sheridan, AR / Fayetteville, AR, US) in 2020. Personal training and coaching platform. Processes workout plans, progress photos (EXTREME sensitivity — body images), nutrition logs, client health data. Was Canadian — no longer. CLOUD Act applies.", risk:"exposed", category:"fitness", industries:["fitness","wellness"] },
      { name:"WellnessLiving", parent:"WellnessLiving Systems Inc.", hq:"Thornhill, ON", jurisdiction:"Canada", cloudAct:false, dataResidency:"Canada", note:"Canadian-incorporated fitness and wellness business management platform. Thornhill, Ontario HQ. Raised $66M from McCarthy Capital (US PE) + CIBC Innovation Banking (Aug 2022). McCarthy Capital investment noted but company remains Canadian-incorporated with Canadian HQ. Direct Canadian alternative to Mindbody.", risk:"canadian", category:"fitness", industries:["fitness","wellness"] },
      { name:"GymMaster", parent:"Treshna Enterprises Ltd.", hq:"Tauranga, New Zealand", jurisdiction:"New Zealand", cloudAct:false, dataResidency:"NZ/Global", note:"New Zealand-incorporated gym management software. NZ Privacy Act 2020 provides strong protections. EU GDPR adequacy finding. Not subject to CLOUD Act. Low-risk foreign jurisdiction — comparable to TaxCycle/Xero analysis.", risk:"non_exposed", category:"fitness", industries:["fitness","wellness"] },
      { name:"Zeffy", parent:"Zeffy Inc. (formerly Simplyk)", hq:"Montreal, QC", jurisdiction:"Canada", cloudAct:false, dataResidency:"Canada", note:"Montreal-based (Quebec-incorporated) 100% free fundraising platform for nonprofits. Zero fees on donations — funded by optional donor tips. Canadian-parented. Direct alternative to US donation platforms. Processes donor names, emails, payment data, donation history.", risk:"canadian", category:"nonprofit", industries:["nonprofit"] },
      { name:"ChatGPT", parent:"OpenAI Inc.", hq:"San Francisco, CA", jurisdiction:"United States", cloudAct:true, dataResidency:"US", note:"US-incorporated AI assistant. Free/Plus tier prompts may be used for model training — users paste client data, source code, business documents into US AI infrastructure. Enterprise/Team tiers offer data retention controls. CLOUD Act applies. HIGHER RISK for Free/Plus users who input sensitive business data.", risk:"exposed", category:"ai", industries:["technology","legal","accounting","healthcare","general"] },
      { name:"WordPress / Automattic", parent:"Automattic Inc.", hq:"San Francisco, CA", jurisdiction:"United States", cloudAct:true, dataResidency:"US/Global", note:"US-incorporated. WordPress.com hosted sites and WooCommerce process visitor data, form submissions, customer records through US infrastructure. Self-hosted WordPress.org on Canadian servers avoids this — but WordPress.com (hosted) is fully US-jurisdictioned. Automattic also owns Tumblr, WooCommerce, Jetpack.", risk:"review", category:"website", industries:["technology","general","nonprofit"] },
      { name:"Instagram / Meta", parent:"Meta Platforms Inc. (NASDAQ: META)", hq:"Menlo Park, CA", jurisdiction:"United States", cloudAct:true, dataResidency:"US", note:"US-incorporated social media platform. Business accounts process customer engagement data, DM conversations, ad targeting data, follower demographics. Used as marketing channel by virtually every small business. All interaction data under US jurisdiction. Meta has extensive government data request compliance history.", risk:"exposed", category:"marketing", industries:["general","fitness","real_estate","hospitality"] },
      { name:"uLawPractice", parent:"Superfluid Software Inc.", hq:"Toronto, ON", jurisdiction:"Canada", cloudAct:false, dataResidency:"Canada", note:"Canadian-incorporated cloud-based legal practice management and accounting software. Built specifically for Canadian lawyers with integrated trust accounting compliant with Law Society rules. Toronto HQ. Canadian alternative to US practice management tools.", risk:"canadian", category:"legal", industries:["legal"] },
      { name:"Adobe Acrobat", parent:"Adobe Inc. (NASDAQ: ADBE)", hq:"San Jose, CA", jurisdiction:"United States", cloudAct:true, dataResidency:"US", note:"US-incorporated. PDF editing and document management. Risk depends on cloud sync — Adobe Creative Cloud syncs documents through US infrastructure. Disable cloud sync to avoid transfer. Desktop-only use without cloud features does not trigger TIA. Critical: Adobe cloud stores full document content including legal instruments and redaction metadata.", risk:"review", category:"productivity", industries:["legal","accounting","general"] },
      { name:"Taxprep / CCH iFirm", parent:"Wolters Kluwer N.V.", hq:"Amsterdam, Netherlands", jurisdiction:"Netherlands / EU", cloudAct:false, dataResidency:"EU/Canada", note:"Dutch-incorporated (Euronext: WKL). Dominant professional tax preparation software in Canada alongside TaxCycle. CCH iFirm provides practice management and document management. GDPR jurisdiction — strongest privacy framework globally. Desktop installations store data locally (no transfer). CCH iFirm cloud routes through Wolters Kluwer infrastructure. Not subject to CLOUD Act.", risk:"non_exposed", category:"accounting", industries:["accounting"] },
      { name:"Epitech Integrator", parent:"Epitech Software Inc.", hq:"Salt Spring Island, BC", jurisdiction:"Canada", cloudAct:false, dataResidency:"Canada", note:"Canadian standalone entity. No parent companies. Data integration platform. Headquartered on Salt Spring Island, BC. 100% Canadian-owned and operated. Not subject to any foreign data access laws.", risk:"canadian", category:"technology", industries:["technology"] },
      { name:"Tailscale", parent:"Tailscale Inc.", hq:"Toronto, ON", jurisdiction:"Canada", cloudAct:false, dataResidency:"Global", note:"Toronto-headquartered (founded 2019 by former Google engineers). Canadian-incorporated. Zero-config WireGuard VPN for secure connectivity. $275M raised from US VCs (Accel, CRV, Insight Partners). Valuation $1.5B (2025). All major investors are US-based — no US parent entity but significant US VC influence. Acquired Border0 (Vancouver PAM startup) March 2026. Expanding to 400 employees globally. No known US subsidiary or US commercial operations — but US VC board seats may create governance nexus questions. Classified as review pending deeper corporate structure verification.", risk:"review", category:"cybersecurity", industries:["technology"] },
      { name:"Border0", parent:"Tailscale Inc. (acquired March 2026)", hq:"Vancouver, BC (now Toronto via Tailscale)", jurisdiction:"Canada", cloudAct:false, dataResidency:"Global", note:"Vancouver-based privileged access management (PAM) startup acquired by Tailscale (Toronto) in March 2026. Entire 7-person team joined Tailscale. Founder Andree Toonk became Director of Engineering at Tailscale. Border0 manages access to sensitive infrastructure — production systems, databases, Kubernetes. Now part of Tailscale's product suite. Jurisdiction follows Tailscale parent — Canadian-incorporated but US VC-backed. Same review status as Tailscale.", risk:"review", category:"cybersecurity", industries:["technology"] },
      { name:"Fathom", parent:"Fathom Video Inc.", hq:"San Francisco, CA", jurisdiction:"United States", cloudAct:true, dataResidency:"US", note:"US-incorporated (San Francisco) AI meeting notetaker. Records, transcribes, and summarizes meetings on Zoom, Google Meet, Teams. Founded 2020. $22M raised (Series A led by Telescope Partners). Zoom is an investor. All meeting audio, transcripts, summaries, and action items flow through US infrastructure. CLOUD Act applies. CRITICAL RISK: captures full audio of sensitive business meetings — client discussions, strategy sessions, HR conversations, legal calls. One of the highest-risk categories for data sovereignty.", risk:"exposed", category:"ai", industries:["technology","legal","healthcare","general"] },
      { name:"Fellow", parent:"Fellow Insights Inc.", hq:"Ottawa, ON", jurisdiction:"Canada", cloudAct:false, dataResidency:"Canada", note:"Ottawa-headquartered (Canadian-incorporated) AI meeting assistant and notetaker. Founded 2017 by Aydin Mirzaee, Amin Mirzaee, Samuel Cormier-Iijima (previously founded Fluidware, acquired by SurveyMonkey). $30.5M total raised across two rounds. Seed ($6.5M, 2019): led by Inovia Capital (Montreal — Canadian VC), with Felicis Ventures (San Francisco) and Garage Capital (Kitchener — Canadian, founded by Vidyard co-founders). Series A ($24M, 2021): led by Craft Ventures (San Francisco — David Sacks' firm), with participation from Inovia, Felicis, Formentera, and Silicon Valley Bank. Majority of capital from US VCs — Craft Ventures and Felicis likely hold board seats and significant governance influence. No known US subsidiary or US commercial operations. Records and transcribes meetings, generates summaries, action items. Integrates with Zoom, Google Meet, Teams, Slack, Salesforce. First customer was Shopify. Classified as review: Canadian-incorporated and Ottawa-headquartered but US VC governance influence mirrors Tailscale profile. Processes sensitive meeting audio and transcripts.", risk:"review", category:"ai", industries:["technology","general"] },
      { name:"Read.AI", parent:"Read AI Inc.", hq:"Seattle, WA", jurisdiction:"United States", cloudAct:true, dataResidency:"US", note:"US-incorporated (Delaware). Seattle-headquartered AI meeting assistant. Founded 2021 by David Shim (former Foursquare CEO). $81M raised (Series B). SOC 2 certified. Records meetings, transcribes, summarizes, tracks action items across meetings, email, and messaging. Works across Zoom, Teams, Google Meet. CLOUD Act applies. Same critical risk as Fathom — captures full audio and transcripts of sensitive business meetings. All data under US jurisdiction.", risk:"exposed", category:"ai", industries:["technology","general"] },
      { name:"FunctionFox", parent:"Volaris Group (Constellation Software Inc.)", hq:"Victoria, BC", jurisdiction:"Canada", cloudAct:false, dataResidency:"Canada", note:"Victoria BC-headquartered timesheet and project management software for creative agencies. Founded 2000. Acquired by Volaris Group (May 2023), an operating group of Constellation Software Inc. (TSX: CSU, Toronto). Canadian-incorporated parent. No US parent entity. $6.4M revenue (2024). ~16 employees. Niche — serves creative teams, not general-purpose PM.", risk:"canadian", category:"project_management", industries:["technology","general"] },
      { name:"Nutcache", parent:"Dynacom Technologies", hq:"Laval, QC", jurisdiction:"Canada", cloudAct:false, dataResidency:"Canada", note:"Laval QC-headquartered project management and invoicing SaaS. Part of Dynacom Technologies Group (founded 1990 by Alain Nadeau). Canadian-owned and operated. Nutcache launched 2013. Combines task management, time tracking, and invoicing. ~900 customers. Niche — targets freelancers and small teams.", risk:"canadian", category:"project_management", industries:["technology","general"] },
      { name:"Birdview PSA", parent:"Logic Software Inc.", hq:"Toronto, ON", jurisdiction:"Canada", cloudAct:false, dataResidency:"Canada", note:"Toronto-headquartered PSA and project management platform. Developed by Logic Software Inc. (Canadian). Canadian-based hosting. Serves IT, consulting, engineering, professional services. Supports multi-currency including CAD. Available in English and French. Niche — targets professional services firms, not general-purpose PM.", risk:"canadian", category:"project_management", industries:["technology","general"] },
      { name:"Agility CMS", parent:"Agility Inc.", hq:"Vancouver, BC", jurisdiction:"Canada", cloudAct:false, dataResidency:"Canada", note:"Vancouver BC-headquartered headless content management system. Canadian-founded and operated. Cloud-based CMS with page management, content modeling, and API-first architecture. Niche — targets developers and enterprise content teams.", risk:"canadian", category:"cms", industries:["technology","general"] },
      { name:"QuickSilk", parent:"QuickSilk Inc.", hq:"Ottawa, ON", jurisdiction:"Canada", cloudAct:false, dataResidency:"Canada", note:"Ottawa-headquartered cloud-based CMS. Founded 2010. Canadian-owned and operated. Emphasizes security (claims zero breaches). Niche — targets small-to-mid-size organizations needing simple website management.", risk:"canadian", category:"cms", industries:["technology","general"] }
